/**
 * Climate Predictions and Analysis Domain Types (Server)
 *
 * Strict data provenance separation:
 * A. REAL_EXTERNAL_DATA - Direct satellite/sensor measurements (NASA POWER, Open-Meteo telemetry, OpenWeather)
 * B. DERIVED_CALCULATION - Deterministic mathematical calculations (OLS regression, threshold risk scores)
 * C. AI_INTERPRETATION - Decision support synthesis generated by AI reasoning layer (Gemini)
 * D. MODEL_PROJECTION - Scenario-projected future estimates (Baseline, Resilience, Accelerated)
 * E. DEMO_DATA - Explicitly tagged mock/fallback data if real providers are unavailable
 */

export type DataProvenanceType =
  | 'REAL_EXTERNAL_DATA'
  | 'DERIVED_CALCULATION'
  | 'AI_INTERPRETATION'
  | 'MODEL_PROJECTION'
  | 'DEMO_DATA';

export interface DataProvenance {
  type: DataProvenanceType;
  source: string;
  method?: string;
  confidence?: number | string | null;
  baselinePeriod?: string;
  notes?: string;
}

export type RiskLevel = 'VERY_LOW' | 'LOW' | 'MEDIUM' | 'HIGH' | 'VERY_HIGH';

export interface TemperatureTrendIndicator {
  value: number;
  unit: string;
  baselineValue: number;
  anomaly: number;
  annualRate: number;
  rSquared: number | null;
  confidence: string;
  provenance: DataProvenance;
}

export interface PrecipitationTrendIndicator {
  value: number;
  unit: string;
  baselineValue: number;
  changePercent: number;
  annualRate: number;
  rSquared: number | null;
  confidence: string;
  provenance: DataProvenance;
}

export interface HeatRiskIndicator {
  level: RiskLevel;
  score: number; // 0 to 1
  extremeHeatDaysProjected: number;
  thresholdTemp: number;
  provenance: DataProvenance;
}

export interface FloodWaterRiskIndicator {
  level: RiskLevel;
  score: number; // 0 to 1
  precipitationAnomalyPercent: number;
  retentionCapacityScore: number;
  provenance: DataProvenance;
}

export interface DroughtWaterStressIndicator {
  level: RiskLevel;
  score: number; // 0 to 1
  soilMoistureIndex: number;
  stressLevel: string;
  provenance: DataProvenance;
}

export interface OverallClimateRiskIndicator {
  level: RiskLevel;
  score: number; // 0 to 100
  primaryDriver: string;
  contributingFactors: string[];
  provenance: DataProvenance;
}

export interface ClimateIndicators {
  temperatureTrend: TemperatureTrendIndicator;
  precipitationTrend: PrecipitationTrendIndicator;
  heatRisk: HeatRiskIndicator;
  floodRisk: FloodWaterRiskIndicator;
  droughtRisk: DroughtWaterStressIndicator;
  overallRisk: OverallClimateRiskIndicator;
}

export type ScenarioType = 'default' | 'resilience' | 'accelerated';

export interface ScenarioDefinition {
  id: ScenarioType;
  name: string;
  tag: string;
  description: string;
  radiativeForcing: string;
  assumptions: string[];
}

export interface ObservedBaseline {
  period: string;
  avgTemperature: number;
  avgPrecipitation: number;
  soilMoisture: number | null;
  aqi: number | null;
  dataPointsCount: number;
  source: string;
  provenance: DataProvenance;
}

export interface AIClimateInterpretation {
  executiveSummary: string;
  riskAssessment: string;
  resilienceOpportunities: string[];
  confidenceAssessment: string;
  provenance: DataProvenance;
}

export interface ProvenanceSummary {
  realExternalSources: string[];
  derivedMethods: string[];
  aiModels: string[];
  limitations: string[];
}

export interface ClimateAnalysisModel {
  location: {
    id: string;
    name: string;
    latitude: number;
    longitude: number;
  };
  targetYear: number;
  scenario: ScenarioDefinition;
  indicators: ClimateIndicators;
  observedBaseline: ObservedBaseline;
  aiInterpretation: AIClimateInterpretation;
  provenanceSummary: ProvenanceSummary;
}
